UPDATE T_MP_ADJUST_STRUCTURE_IN
SET ACTUAL_ADJUST_QTY = CASE

        WHEN MATERIAL_CODE = SUBSTRING_INDEX(#{key}, '|', 1)
             AND CONSTRUCTION_STAGE = SUBSTRING_INDEX(#{key}, '|', -1)
        THEN #{qty}

    ELSE ACTUAL_ADJUST_QTY
END
WHERE FACTORY_CODE = #{factoryCode}
  AND YEAR = #{year}
  AND MONTH = #{month}
  AND VERSION = #{version}
  AND (MATERIAL_CODE, CONSTRUCTION_STAGE) IN

    (SUBSTRING_INDEX(#{key}, '|', 1), SUBSTRING_INDEX(#{key}, '|', -1))

mapper.select:
SELECT DISTINCT
VERSION
FROM
T_MP_ADJUST_STRUCTURE_IN
WHERE
IS_DELETE = 0 AND VERSION IS NOT NULL
AND FACTORY_CODE = #{factoryCode}
AND YEAR = #{year}
AND MONTH = #{month}
ORDER BY VERSION DESC
